defmodule Ledger.Money do
  @moduledoc """
  A money value with exactly two fields: `:currency` (an atom) and `:amount` (integer count of minor units).
  """

  defstruct [:currency, :amount]

  @typedoc "A money value with currency and an integer amount of minor units."
  @type t :: %__MODULE__{currency: atom(), amount: integer()}

  @type currency :: :bhd | :eur | :jpy | :usd

  @doc "Returns supported currencies in the canonical order."
  def currencies, do: [:bhd, :eur, :jpy, :usd]

  @doc "Returns the exponent of a supported currency."
  def exponent(:bhd), do: 3
  def exponent(:eur), do: 2
  def exponent(:jpy), do: 0
  def exponent(:usd), do: 2

  @doc "Returns `{:ok, money}` or `{:error, :invalid_amount | :unknown_currency}`."
  def new(amount, currency)
  def new(amount, currency) when not is_integer(amount), do: {:error, :invalid_amount}
  def new(_amount, currency) when currency not in [:bhd, :eur, :jpy, :usd], do: {:error, :unknown_currency}
  def new(amount, currency), do: {:ok, %__MODULE__{currency: currency, amount: amount}}

  @doc "Same as `new/2` but raises `ArgumentError` on failure."
  def new!(amount, currency) do
    case new(amount, currency) do
      {:ok, money} -> money
      {:error, reason} -> raise ArgumentError, "money new! failure: #{inspect(reason)}"
    end
  end

  @doc "Returns a money value with amount `0` for the currency."
  def zero(currency), do: new!(0, currency)

  @doc "Adds two money values; `{:ok, money}` or `{:error, :currency_mismatch}`."
  def add(left, right)
  def add(%__MODULE__{} = left, %__MODULE__{} = right) do
    if left.currency == right.currency do
      {:ok, %__MODULE__{left | amount: left.amount + right.amount}}
    else
      {:error, :currency_mismatch}
    end
  end

  @doc "Subtracts two money values; `{:ok, money}` or `{:error, :currency_mismatch}`."
  def subtract(left, right)
  def subtract(%__MODULE__{} = left, %__MODULE__{} = right) do
    if left.currency == right.currency do
      {:ok, %__MODULE__{left | amount: left.amount - right.amount}}
    else
      {:error, :currency_mismatch}
    end
  end

  @doc "Multiplies money by an integer factor; `{:ok, money}` or `{:error, :invalid_factor}`."
  def multiply(%__MODULE__{} = money, factor) when is_integer(factor) do
    {:ok, %__MODULE__{money | amount: money.amount * factor}}
  end
  def multiply(%__MODULE__{}, _factor), do: {:error, :invalid_factor}

  @doc "Sums a list of money values; `{:ok, money}` or `{:error, :currency_mismatch}`."
  def sum(money_list, currency) do
    Enum.reduce_while(money_list, {:ok, zero(currency)}, fn
      %__MODULE__{currency: ^currency} = money, {:ok, acc} ->
        {:cont, add(acc, money)}
      _money, {:ok, _acc} ->
        {:halt, {:error, :currency_mismatch}}
    end)
  end

  @doc "Returns `:lt`, `:eq` or `:gt`. Raises `ArgumentError` when currencies differ."
  def compare(left, right)
  def compare(%__MODULE__{currency: curr, amount: l}, %__MODULE__{currency: curr, amount: r}) when l < r, do: :lt
  def compare(%__MODULE__{currency: curr, amount: l}, %__MODULE__{currency: curr, amount: r}) when l == r, do: :eq
  def compare(%__MODULE__{currency: curr, amount: l}, %__MODULE__{currency: curr, amount: r}) when l > r, do: :gt
  def compare(_left, _right), do: raise(ArgumentError, "cannot compare different currencies")

  @doc "The canonical string form (uppercase code, space, major units with exponent)."
  def to_string(%__MODULE__{currency: currency, amount: amount}) do
    exp = exponent(currency)
    code = currency |> Atom.to_string() |> String.upcase()
    {major, minor} = Integer.div_rem(abs(amount), round(:math.pow(10, exp)))
