      ".#{padding <> minor_str}"
    else
      ""
    end
    "#{code} #{sign}#{major}#{fraction}"
  end

  defimpl String.Chars do
    defdelegate to_string(m), to: Ledger.Money
  end

  defimpl Inspect do
    import Inspect.Algebra
    def inspect(m, opts), do: concat(["#Ledger.Money<", Ledger.Money.to_string(m), ">"])
  end
