    fraction =
      if exp > 0 do
        minor_str = Integer.to_string(minor)
        padding = String.duplicate("0", exp - String.length(minor_str))
        ".#{padding <> minor_str}"
      else
        ""
      end

    "#{code} #{sign}#{major}#{fraction}"
  end

  defimpl String.Chars do
    defdelegate to_string(m), to: Ledger.Money
  end

  defimpl Inspect do
    import Inspect.Algebra
    def inspect(m, _opts), do: concat(["#Ledger.Money<", Ledger.Money.to_string(m), ">"])
  end
end

defmodule Ledger.Money.Type do
  @moduledoc """
  An Ash type for `Ledger.Money` with storage type `:map`.
  """
  use Ash.Type
  alias Ledger.Money

  @impl Ash.Type
  def storage_type, do: :map

  @impl Ash.Type
  def constraints, do: [
    currencies: [type: {:list, :atom}, doc: "Allowed currency atoms"],
    multiple_of: [type: :integer, doc: "Amount must be a multiple of this many minor units"],
    min: [type: :any, doc: "Inclusive minimum bound"],
    max: [type: :any, doc: "Inclusive maximum bound"]
  ]

  @impl Ash.Type
  def cast_input(nil, _opts), do: {:ok, nil}
  def cast_input(%Money{} = m, _opts), do: {:ok, m}
  def cast_input(map, _opts) when is_map(map) do
    c = map[:currency] || map["currency"]
    a = map[:amount] || map["amount"]

    case resolve_currency(c) do
      {:error, reason} -> {:error, message: "unknown currency", reason: reason, currency: c}
      {:ok, currency} ->
        case parse_amount(a) do
          {:ok, amount} -> Money.new(amount, currency)
          {:error, reason} -> {:error, message: "amount must be a whole number of minor units", reason: reason}
        end
    end
  end
  def cast_input(s, _opts) when is_binary(s) do
    # Try canonical string format: "CODE amount"
    case String.split(s, " ", parts: 2) do
      [code, amount_s] ->
        case resolve_currency(code) do
          {:error, reason} -> {:error, message: "unknown currency", reason: reason, currency: code}
          {:ok, currency} ->
            case parse_amount(amount_s) do
              {:ok, amount} ->
                # Validate that the canonical string matches this currency's exponent
                expected = Money.to_string(Money.new!(amount, currency))
                if s == expected do
                  {:ok, Money.new!(amount, currency)}
                else
                  {:error, message: "invalid money format", reason: :invalid_format}
                end
              {:error, reason} -> {:error, message: "amount must be a whole number of minor units", reason: reason}
            end
        end
      _ -> {:error, message: "invalid money format", reason: :invalid_format}
    end
  end
  def cast_input(_other, _opts), do: {:error, message: "invalid money format", reason: :invalid_format}

  @impl Ash.Type
  def cast_stored(nil, _opts), do: {:ok, nil}
  def cast_stored(%{currency: c, amount: a}, _opts) when is_atom(c) and is_integer(a) do
    Money.new(a, c)
  end
  def cast_stored(_other, _opts), do: {:error, message: "invalid money format", reason: :invalid_format}

  @impl Ash.Type
  def dump_to_native(nil, _opts), do: {:ok, nil}
  def dump_to_native(%Money{currency: c, amount: a}, _opts), do: {:ok, %{currency: c, amount: a}}
  def dump_to_native(_other, _opts), do: {:error, :cannot_dump}

  @impl Ash.Type
  def apply_constraints(nil, _opts), do: {:ok, nil}
  def apply_constraints(%Money{} = money, opts) do
    # :currencies, :multiple_of, :min, :max — ordered
    with :ok <- check_currencies(money, opts[:currencies]),
         :ok <- check_multiple_of(money, opts[:multiple_of]),
         :ok <- check_min(money, opts[:min]),
         :ok <- check_max(money, opts[:max]) do
      {:ok, money}
    end
  end

  # --- Internal Helpers ---

  defp resolve_currency(c) when is_atom(c), do: if(c in Money.currencies(), do: {:ok, c}, else: {:error, :unknown_currency})
  defp resolve_currency(s) when is_binary(s) do
    case String.downcase(s) |> String.to_existing_atom() do
      a when a in [:bhd, :eur, :jpy, :usd] -> {:ok, a}
      _ -> {:error, :unknown_currency}
    end
  rescue
    ArgumentError -> {:error, :unknown_currency}
  end
  defp resolve_currency(_other), do: {:error, :unknown_currency}

  defp parse_amount(a) when is_integer(a), do: {:ok, a}
  defp parse_amount(s) when is_binary(s) do
    if String.match?(s, ~r/^-?[0-9]+$/), do: {:ok, String.to_integer(s)}, else: {:error, :fractional_minor_units}
  end
  defp parse_amount(_), do: {:error, :fractional_minor_units}

  defp check_currencies(_money, nil), do: :ok
  defp check_currencies(%Money{currency: c}, allowed) when is_list(allowed) do
    if c in allowed, do: :ok, else: {:error, message: "currency is not allowed", reason: :currency_not_allowed, currency: c}
  end

  defp check_multiple_of(_money, nil), do: :ok
  defp check_multiple_of(%Money{amount: a}, m) when is_integer(m) and m > 0 do
    if rem(a, m) == 0, do: :ok, else: {:error, message: "must be a multiple of %{multiple_of} minor units", reason: :not_multiple_of, multiple_of: m}
  end

  defp check_min(%Money{} = money, min_val) when not is_nil(min_val) do
    case cast_input(min_val, []) do
      {:ok, %Money{currency: c, amount: ma}} ->
        if money.currency == c do
          if money.amount >= ma, do: :ok, else: {:error, message: "must be greater than or equal to %{min}", reason: :below_min, min: Money.to_string(Money.new!(ma, c))}
        else
          {:error, message: "cannot compare money in different currencies", reason: :currency_mismatch}
        end
      {:ok, nil} -> :ok # Should not happen
      {:error, _} -> :ok # Ignore invalid bound
    end
  end
  defp check_min(_money, _nil), do: :ok

  defp check_max(%Money{} = money, max_val) when not is_nil(max_val) do
    case cast_input(max_val, []) do
      {:ok, %Money{currency: c, amount: ma}} ->
        if money.currency == c do
          if money.amount <= ma, do: :ok, else: {:error, message: "must be less than or equal to %{max}", reason: :above_max, max: Money.to_string(Money.new!(ma, c))}
        else
          {:error, message: "cannot compare money in different currencies", reason: :currency_mismatch}
        end
      {:ok, nil} -> :ok
      {:error, _} -> :ok
    end
  end
  defp check_max(_money, _nil), do: :ok
end

defmodule Ledger.Money do
  @moduledoc """
  A money value with exactly two fields: `:currency` (an atom) and `:amount` (integer count of minor units).
  """

  defstruct [:currency, :amount]

  @typedoc "A money value with currency and an integer amount of minor units."
  @type t :: %__MODULE__{currency: atom(), amount: integer()}

  @type currency :: :bhd | :eur | :jpy | :usd

  @doc "Returns supported currencies in the canonical order."
  def currencies, do: [:bhd, :eur, :jpy, :usd]

  @doc "Returns the exponent of a supported currency."
  def exponent(:bhd), do: 3
  def exponent(:eur), do: 2
  def exponent(:jpy), do: 0
  def exponent(:usd), do: 2

  @doc "Returns `{:ok, money}` or `{:error, :invalid_amount | :unknown_currency}`."
  def new(amount, currency)
  def new(amount, _currency) when not is_integer(amount), do: {:error, :invalid_amount}
  def new(_amount, currency) when currency not in [:bhd, :eur, :jpy, :usd], do: {:error, :unknown_currency}
  def new(amount, currency), do: {:ok, %__MODULE__{currency: currency, amount: amount}}

  @doc "Same as `new/2` but raises `ArgumentError` on failure."
  def new!(amount, currency) do
    case new(amount, currency) do
      {:ok, money} -> money
      {:error, reason} -> raise ArgumentError, "money new! failure: #{inspect(reason)}"
    end
  end

  @doc "Returns a money value with amount `0` for the currency."
  def zero(currency), do: new!(0, currency)

  @doc "Adds two money values; `{:ok, money}` or `{:error, :currency_mismatch}`."
  def add(left, right)
  def add(%__MODULE__{} = left, %__MODULE__{} = right) do
    if left.currency == right.currency do
      {:ok, %__MODULE__{left | amount: left.amount + right.amount}}
    else
      {:error, :currency_mismatch}
    end
  end

  @doc "Subtracts two money values; `{:ok, money}` or `{:error, :currency_mismatch}`."
  def subtract(left, right)
  def subtract(%__MODULE__{} = left, %__MODULE__{} = right) do
    if left.currency == right.currency do
      {:ok, %__MODULE__{left | amount: left.amount - right.amount}}
    else
      {:error, :currency_mismatch}
    end
  end

  @doc "Multiplies money by an integer factor; `{:ok, money}` or `{:error, :invalid_factor}`."
  def multiply(%__MODULE__{} = money, factor) when is_integer(factor) do
    {:ok, %__MODULE__{money | amount: money.amount * factor}}
  end
  def multiply(%__MODULE__{}, _factor), do: {:error, :invalid_factor}

  @doc "Sums a list of money values; `{:ok, money}` or `{:error, :currency_mismatch}`."
  def sum(money_list, currency) do
    Enum.reduce_while(money_list, {:ok, zero(currency)}, fn
      %__MODULE__{currency: ^currency} = money, {:ok, acc} ->
        {:cont, add(acc, money)}
      _money, {:ok, _acc} ->
        {:halt, {:error, :currency_mismatch}}
    end)
  end

  @doc "Returns `:lt`, `:eq` or `:gt`. Raises `ArgumentError` when currencies differ."
  def compare(left, right)
  def compare(%__MODULE__{currency: curr, amount: l}, %__MODULE__{currency: curr, amount: r}) when l < r, do: :lt
  def compare(%__MODULE__{currency: curr, amount: l}, %__MODULE__{currency: curr, amount: r}) when l == r, do: :eq
  def compare(%__MODULE__{currency: curr, amount: l}, %__MODULE__{currency: curr, amount: r}) when l > r, do: :gt
  def compare(_left, _right), do: raise(ArgumentError, "cannot compare different currencies")

  @doc "The canonical string form (uppercase code, space, major units with exponent)."
  def to_string(%__MODULE__{currency: currency, amount: amount}) do
    exp = exponent(currency)
    code = currency |> Atom.to_string() |> String.upcase()
    divisor = round(:math.pow(10, exp))
    abs_amount = abs(amount)
    major = div(abs_amount, divisor)
    minor = rem(abs_amount, divisor)
    sign = if amount < 0, do: "-", else: ""

    fraction =
      if exp > 0 do
        minor_str = Integer.to_string(minor)
        padding = String.duplicate("0", exp - String.length(minor_str))
        ".#{padding <> minor_str}"
      else
        ""
      end

    "#{code} #{sign}#{major}#{fraction}"
  end

  defimpl String.Chars do
    defdelegate to_string(m), to: Ledger.Money
  end

  defimpl Inspect do
    import Inspect.Algebra
    def inspect(m, _opts), do: concat(["#Ledger.Money<", Ledger.Money.to_string(m), ">"])
  end
end
